-- Proposed F3a interface; explicit installer owns marker/checksum/registry.
-- Native records/events/changes remain sole authority; no second award ledger.
CREATE TABLE "contest_terms"(branch TEXT NOT NULL,id TEXT NOT NULL,"contract" TEXT NOT NULL CHECK("contract" IS NULL OR json_valid("contract")),"terms_digest" TEXT NOT NULL,"resource_preimages" TEXT NOT NULL CHECK("resource_preimages" IS NULL OR json_valid("resource_preimages")),"defined_by" TEXT NOT NULL,PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "contest_consent"(branch TEXT NOT NULL,id TEXT NOT NULL,"terms" TEXT NOT NULL,"entrant" TEXT NOT NULL,"choice" TEXT NOT NULL CHECK("choice" IN ('accepted','declined','withdrawn')),"terms_digest" TEXT NOT NULL,PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"terms") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"entrant") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "contest_settlement"(branch TEXT NOT NULL,id TEXT NOT NULL,"terms" TEXT NOT NULL,"terms_digest" TEXT NOT NULL,"beneficiary" TEXT NOT NULL,"amount" INTEGER NOT NULL,"unit" TEXT NOT NULL,"pool" TEXT NOT NULL,"destination" TEXT NOT NULL,"terminal_event" TEXT NOT NULL,"proof" TEXT NOT NULL CHECK("proof" IS NULL OR json_valid("proof")),PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"terms") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"beneficiary") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"pool") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"destination") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TRIGGER contest_terms_no_update BEFORE UPDATE ON "contest_terms" BEGIN SELECT RAISE(ABORT,'immutable contest fact'); END;
CREATE TRIGGER contest_terms_no_delete BEFORE DELETE ON "contest_terms" BEGIN SELECT RAISE(ABORT,'immutable contest fact'); END;
CREATE TRIGGER contest_settlement_no_update BEFORE UPDATE ON "contest_settlement" BEGIN SELECT RAISE(ABORT,'immutable contest fact'); END;
CREATE TRIGGER contest_settlement_no_delete BEFORE DELETE ON "contest_settlement" BEGIN SELECT RAISE(ABORT,'immutable contest fact'); END;
CREATE TRIGGER contest_records_no_update BEFORE UPDATE ON records WHEN OLD.domain IN ('contest_terms','contest_settlement') BEGIN SELECT RAISE(ABORT,'immutable contest record'); END;
CREATE TRIGGER contest_records_no_delete BEFORE DELETE ON records WHEN OLD.domain IN ('contest_terms','contest_settlement') BEGIN SELECT RAISE(ABORT,'immutable contest record'); END;
CREATE TRIGGER contest_consent_no_delete BEFORE DELETE ON contest_consent BEGIN SELECT RAISE(ABORT,'consent history cannot be deleted'); END;
CREATE TRIGGER contest_consent_records_no_delete BEFORE DELETE ON records WHEN OLD.domain='contest_consent' BEGIN SELECT RAISE(ABORT,'consent record cannot be deleted'); END;
CREATE TRIGGER contest_consent_withdraw_only BEFORE UPDATE ON contest_consent WHEN OLD.choice<>'accepted' OR NEW.choice<>'withdrawn' OR NEW.branch<>OLD.branch OR NEW.id<>OLD.id OR NEW.terms<>OLD.terms OR NEW.entrant<>OLD.entrant OR NEW.terms_digest<>OLD.terms_digest BEGIN SELECT RAISE(ABORT,'only explicit accepted consent withdrawal'); END;
CREATE TRIGGER contest_consent_settled_no_insert BEFORE INSERT ON contest_consent WHEN EXISTS(SELECT 1 FROM contest_settlement WHERE branch=NEW.branch AND terms=NEW.terms) BEGIN SELECT RAISE(ABORT,'settled consent cannot change'); END;
CREATE TRIGGER contest_consent_settled_no_update BEFORE UPDATE ON contest_consent WHEN EXISTS(SELECT 1 FROM contest_settlement WHERE branch=NEW.branch AND terms=NEW.terms) BEGIN SELECT RAISE(ABORT,'settled consent cannot change'); END;
CREATE UNIQUE INDEX contest_terms_identity ON contest_terms(branch,json_extract(contract,'$.contest_id'));
CREATE UNIQUE INDEX contest_one_consent ON contest_consent(branch,terms,entrant);
CREATE UNIQUE INDEX contest_one_settlement ON contest_settlement(branch,terms);
CREATE TRIGGER contest_consent_record_metadata BEFORE UPDATE ON records WHEN OLD.domain='contest_consent' AND (NEW.domain<>OLD.domain OR NEW.branch<>OLD.branch OR NEW.id<>OLD.id OR OLD.version<>1 OR NEW.version<>2 OR NEW.status<>OLD.status OR NEW.visibility<>OLD.visibility OR NEW.audience_json<>OLD.audience_json) BEGIN SELECT RAISE(ABORT,'consent metadata changes limited to one explicit withdrawal'); END;
